/** Splits a remote command line on whitespace; the remote shell parses it again anyway. */
export const remoteCommandArgv = (line: string | undefined): ReadonlyArray<string> | null => {
  const argv = (line ?? "")
    .trim()
    .split(/\s+/)
    .filter((part) => part !== "");

  return argv.length === 0 ? null : argv;
};

